#!/bin/bash
# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: first-run bootstrap for a fresh Omarchy machine, so one command gives it both the
# delulu-smash framework and the OS setup: installs uv (not in stock Omarchy), runs the root
# .install.sh (Python environment, pre-commit hook, git-lfs data, AI Gateway key), then `os sync`,
# which sets the machine up from .os/machine.toml. Afterwards a new terminal has the `os` alias.
#
# Example CLI Commands:
#   1. New machine:  git clone <repo> ~/repos/delulu-smash && ~/repos/delulu-smash/.os/install.sh
#   2. Preview the OS changes (skips the framework): ~/repos/delulu-smash/.os/install.sh --dry-run
# ---------------------------------------------------------------------------
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
command -v uv >/dev/null || sudo pacman -S --needed --noconfirm uv
# The framework first: it only asks for the AI Gateway key (skippable). A preview run skips it.
[[ " $* " == *" --dry-run "* ]] || bash "$repo/.install.sh"
exec uv run "$repo/.os/cli.py" sync "$@"
